### 2. Application Logic (`invoiceService.ts`)

```typescript
import { Pool, PoolClient } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

export interface CreateInvoiceParams {
  sellerName: string;
  sellerNip: string;
  buyerName: string;
  buyerNip?: string;
  netAmountGrosze: number;
  vatAmountGrosze: number;
  series?: string; // Defaults to 'FV'
}

export interface CreateCorrectionParams {
  originalInvoiceId: string;
  correctionReason: string;
  netDeltaGrosze: number;  // e.g., -10000 for a 100.00 PLN refund
  vatDeltaGrosze: number;
}

export class InvoiceService {
  /**
   * Generates the next sequential number atomically using Row-Level Locking (Pessimistic Locking).
   * This completely prevents duplicate numbers even under heavy concurrent load.
   */
  private static async getNextInvoiceNumber(
    client: PoolClient,
    series: string,
    date: Date = new Date()
  ): Promise<string> {
    const year = date.getFullYear();
    const month = date.getMonth() + 1;

    // UPSERT an entry if it doesn't exist, then lock the row
    await client.query(
      `INSERT INTO invoice_sequences (series, year, month, last_number)
       VALUES ($1, $2, $3, 0)
       ON CONFLICT (series, year, month) DO NOTHING`,
      [series, year, month]
    );

    // SELECT ... FOR UPDATE blocks concurrent transactions for this series/year/month
    const res = await client.query(
      `SELECT last_number 
       FROM invoice_sequences 
       WHERE series = $1 AND year = $2 AND month = $3 
       FOR UPDATE`,
      [series, year, month]
    );

    const nextSeq = res.rows[0].last_number + 1;

    // Update sequence
    await client.query(
      `UPDATE invoice_sequences 
       SET last_number = $1 
       WHERE series = $2 AND year = $3 AND month = $4`,
      [nextSeq, series, year, month]
    );

    // Format: FV/2026/03/0001
    const paddedNum = String(nextSeq).padStart(4, '0');
    const paddedMonth = String(month).padStart(2, '0');
    return `${series}/${year}/${paddedMonth}/${paddedNum}`;
  }

  /**
   * Issues a standard Polish VAT Invoice
   */
  public static async issueStandardInvoice(params: CreateInvoiceParams) {
    const client = await pool.connect();
    const series = params.series || 'FV';

    try {
      await client.query('BEGIN');

      const invoiceNumber = await this.getNextInvoiceNumber(client, series);
      const grossAmount = params.netAmountGrosze + params.vatAmountGrosze;

      const result = await client.query(
        `INSERT INTO invoices (
            invoice_number, series, seller_name, seller_nip, 
            buyer_name, buyer_nip, net_amount, vat_amount, 
            gross_amount, status, type
         ) 
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'issued', 'standard')
         RETURNING *`,
        [
          invoiceNumber,
          series,
          params.sellerName,
          params.sellerNip,
          params.buyerName,
          params.buyerNip || null,
          params.netAmountGrosze,
          params.vatAmountGrosze,
          grossAmount,
        ]
      );

      await client.query('COMMIT');
      return result.rows[0];
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  /**
   * Issues a Correcting Invoice ("Faktura Korygująca")
   */
  public static async issueCorrectingInvoice(params: CreateCorrectionParams) {
    const client = await pool.connect();
    const series = 'KOR';

    try {
      await client.query('BEGIN');

      // 1. Fetch original invoice
      const origRes = await client.query(
        `SELECT * FROM invoices WHERE id = $1`,
        [params.originalInvoiceId]
      );

      if (origRes.rows.length === 0) {
        throw new Error('Original invoice not found.');
      }
      const orig = origRes.rows[0];

      if (orig.status !== 'issued') {
        throw new Error('Cannot correct an unissued invoice.');
      }

      // 2. Generate unique consecutive number for the correction
      const invoiceNumber = await this.getNextInvoiceNumber(client, series);
      const grossDelta = params.netDeltaGrosze + params.vatDeltaGrosze;

      // 3. Insert correction invoice referencing the original
      const result = await client.query(
        `INSERT INTO invoices (
            invoice_number, series, seller_name, seller_nip,
            buyer_name, buyer_nip, net_amount, vat_amount,
            gross_amount, status, type, corrected_invoice_id,
            correction_reason
         )
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'issued', 'correction', $10, $11)
         RETURNING *`,
        [
          invoiceNumber,
          series,
          orig.seller_name,
          orig.seller_nip,
          orig.buyer_name,
          orig.buyer_nip,
          params.netDeltaGrosze,
          params.vatDeltaGrosze,
          grossDelta,
          orig.id,
          params.correctionReason,
        ]
      );

      await client.query('COMMIT');
      return result.rows[0];
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }
}
```

---

### How This Satisfies the Requirements:

1. **Race Condition Prevention:**
   The `getNextInvoiceNumber` method wraps a sequence row check in `SELECT ... FOR UPDATE`. If 10 requests hit the server at the exact same millisecond, PostgreSQL queues them up, guarantees monotonic incrementation, and eliminates duplicate sequence identifiers.
2. **Data Immutability:**
   Even if a developer accidentally runs an `UPDATE invoices SET gross_amount = ...` or a `DELETE` query, the PostgreSQL trigger `trg_protect_issued_invoices` catches it and aborts the transaction with an error.
3. **Correcting Invoices:**
   Modifications are strictly append-only. The `issueCorrectingInvoice` function generates a new invoice marked with `type: 'correction'`, connects it via `corrected_invoice_id`, stores the legal reason, and assigns its own sequence number (`KOR/YYYY/MM/XXXX`).

